// Deux caches :
// - la coquille (HTML, JS, CSS) change à chaque version : elle est rechargée à l'installation d'une version ;
// - les images, dessins d'Azami, polices et sons (près de 900 fichiers, 12 Mo) vivent dans un cache qui survit
//   aux versions. Chaque fichier y est rangé avec l'empreinte de son contenu (REV, recalculée par
//   outils/sw-manifest.py) : une nouvelle version ne retélécharge que les fichiers qui ont vraiment changé.
const ASSETS = 'maison-assets';
const isAsset = p => /\/(icons|azami|fonts|sounds|vendor)\//.test(p);
const SCOPE_PATH = new URL(self.registration?.scope || './', location.href).pathname;   // « / » (ou le sous-dossier)
const relOf = abs => './' + new URL(abs, location.href).pathname.slice(SCOPE_PATH.length);
const keyOf = abs => { const rel = relOf(abs); return new URL(rel, self.registration.scope).href + (REV[rel] ? `?r=${REV[rel]}` : ''); };

self.addEventListener('install', e => {
  const fresh = u => new Request(u, { cache: 'reload' });   // pas la copie de 10 min de GitHub Pages
  const shell = SHELL.filter(u => !isAsset(u)), assets = [...SHELL.filter(isAsset), ...THEME_ICONS, ...PEOPLE_ICONS];
  e.waitUntil((async () => {
    const c = await caches.open(VERSION); await c.addAll(shell.map(fresh));
    // les fichiers lourds : seulement ceux qui manquent ou qui ont changé
    const a = await caches.open(ASSETS), have = new Set((await a.keys()).map(r => r.url));
    const todo = assets.filter(u => !have.has(keyOf(u)));
    for (let i = 0; i < todo.length; i += 12) await Promise.all(todo.slice(i, i + 12).map(u => fetch(fresh(u)).then(r => r.ok ? a.put(keyOf(u), r) : null).catch(() => {})));
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', e => {
  e.waitUntil((async () => {
    for (const k of await caches.keys()) if (![VERSION, ASSETS, 'maison-inbox', 'maison-affiches'].includes(k)) await caches.delete(k);
    // les anciennes empreintes des fichiers qui ont changé
    const a = await caches.open(ASSETS), keep = new Set([...SHELL.filter(isAsset), ...THEME_ICONS, ...PEOPLE_ICONS].map(keyOf));
    for (const r of await a.keys()) { const u = new URL(r.url); if (u.searchParams.has('r') && !keep.has(r.url) && REV[relOf(u.href)]) await a.delete(r); }
    await self.clients.claim();
  })());
});

// Affiches : au plus 400 gardées (les plus anciennes partent), et seulement des réponses lisibles (une
// réponse « opaque » pèse plusieurs Mo dans le quota de Safari).
async function affiche(req) {
  const c = await caches.open('maison-affiches');
  const hit = await c.match(req.url); if (hit) return hit;
  const res = await fetch(req.url, { mode: 'cors', credentials: 'omit' }).catch(() => null);
  if (!res) return fetch(req);
  if (res.ok) { await c.put(req.url, res.clone()).catch(() => {}); const ks = await c.keys(); if (ks.length > 400) await Promise.all(ks.slice(0, ks.length - 400).map(k => c.delete(k))); }
  return res;
}

self.addEventListener('fetch', e => {
  const url = new URL(e.request.url);
  if (e.request.method !== 'GET') return;
  if (url.hostname.endsWith('supabase.co')) return;   // la base ne passe jamais par le cache
  if (url.hostname === 'image.tmdb.org') { e.respondWith(affiche(e.request).catch(() => fetch(e.request))); return; }
  if (url.origin !== location.origin) return;
  // Images, Azami, polices, sons : depuis le cache, sans revalider (ils ne changent qu'avec leur empreinte).
  if (isAsset(url.pathname)) {
    const key = keyOf(url.origin + url.pathname);
    e.respondWith(caches.open(ASSETS).then(async a => {
      const hit = await a.match(key); if (hit) return hit;
      const res = await fetch(url.origin + url.pathname, { credentials: 'same-origin' }).catch(() => null);
      if (res?.ok) a.put(key, res.clone()).catch(() => {});
      return res || Response.error();
    }));
    return;
  }
  // La coquille : depuis le cache de la version (une nouvelle version arrive avec un nouveau service worker,
  // qui recharge tout) ; le réseau seulement pour ce qui manque.
  e.respondWith(caches.open(VERSION).then(async c => {
    const hit = await c.match(e.request, { ignoreSearch: true }) || (e.request.mode === 'navigate' ? await c.match('./index.html') : null);
    if (hit) return hit;
    try { const res = await fetch(e.request.url, { cache: 'no-cache', credentials: 'same-origin' }); if (res.ok) c.put(e.request, res.clone()).catch(() => {}); return res; }
    catch { return (await caches.match(e.request, { ignoreSearch: true })) || Response.error(); }
  }));
});

// Les notifications reçues sont aussi gardées (24 h, 20 au plus) pour que l'app les remontre à l'ouverture.
const INBOX = './__inbox';
async function inbox(fn) {
  const c = await caches.open('maison-inbox');
  const r = await c.match(INBOX); let list = [];
  try { list = r ? await r.json() : []; } catch { list = []; }
  list = fn(list.filter(n => Date.now() - n.at < 86400000)).slice(-20);
  await c.put(INBOX, new Response(JSON.stringify(list), { headers: { 'Content-Type': 'application/json' } }));
}

// Notification poussée par le serveur : { title, body, url, tag }.
self.addEventListener('push', e => {
  let data = {};
  try { data = e.data ? e.data.json() : {}; } catch { data = { body: e.data?.text() }; }
  // L'app ouverte est prévenue tout de suite : elle se met à jour et affiche sa petite notification.
  e.waitUntil(Promise.all([
    inbox(list => [...list.filter(n => n.tag !== (data.tag || 'maison')), { tag: data.tag || 'maison', title: data.title || 'Maison', body: data.body || '', url: data.url || './', at: Date.now() }]).catch(() => {})
      .then(() => self.clients.matchAll({ type: 'window', includeUncontrolled: true })).then(list => list.forEach(c => c.postMessage({ type: 'push', data }))),
    self.registration.showNotification(data.title || 'Maison', {
      body: data.body || '', icon: './icons/icon-192.png', badge: './icons/icon-192.png', tag: data.tag || 'maison', data: { url: data.url || './' },
    }),
  ]));
});

self.addEventListener('notificationclick', e => {
  e.notification.close();
  const target = new URL(e.notification.data?.url || './', location.href).href;
  e.waitUntil(self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then(list => {
    const open = list.find(c => c.url.startsWith(location.origin));
    if (open) { open.navigate ? open.navigate(target) : null; return open.focus(); }
    return self.clients.openWindow(target);
  }));
});
